const root = ReactDOM.createRoot(document.querySelector('#root'));

const courses = [
  { id: 'js', title: '자바스크립트 입문' },
  { id: 'react', title: '리액트 시작하기' },
];
const found = [];

const Grid = ({ list }) => (
  <div className="grid">
    <p className="count">코스 {list.length}개</p>
    {list.length > 0 && list.map((course) => (
      <article className="course" key={course.id}>
        <h3 className="course__title">{course.title}</h3>
      </article>
    ))}
    {list.length === 0 && <p className="empty">조건에 맞는 코스가 없습니다.</p>}
  </div>
);

root.render(
  <>
    <Grid list={courses} />
    <Grid list={found} />
  </>
);

